	private static class ProbeServletOutputStream extends ServletOutputStream {
		private final ByteArrayOutputStream delegate = new ByteArrayOutputStream();
		private final CountDownLatch flushes;
		private volatile int flushCount;

		private ProbeServletOutputStream(int expectedFlushes) {
			flushes = new CountDownLatch(expectedFlushes);
		}

		@Override
		public void write(int value) {
			delegate.write(value);
		}

		@Override
		public void write(byte[] bytes, int offset, int length) {
			delegate.write(bytes, offset, length);
		}

		@Override
		public void flush() throws IOException {
			flushCount++;
			flushes.countDown();
		}

		@Override
		public boolean isReady() {
			return true;
		}

		@Override
		public void setWriteListener(WriteListener writeListener) {
		}

		private byte[] bytes() {
			return delegate.toByteArray();
		}

		private String asString() {
			return delegate.toString(java.nio.charset.StandardCharsets.UTF_8);
		}

	}

	private static final class FailingFlushServletOutputStream extends ProbeServletOutputStream {
		private final CountDownLatch flushAttempted = new CountDownLatch(1);

		private FailingFlushServletOutputStream() {
			super(0);
		}

		@Override
		public void flush() throws IOException {
			flushAttempted.countDown();
			throw new IOException("client disconnected");
		}
	}

	private static final class FinalFlushFailureServletOutputStream extends ProbeServletOutputStream {
		private final CountDownLatch payloadWritten = new CountDownLatch(1);
		private final CountDownLatch releasePayloadWrite = new CountDownLatch(1);
		private volatile boolean failFlush;

		private FinalFlushFailureServletOutputStream() {
			super(0);
		}

		@Override
		public void write(byte[] bytes, int offset, int length) {
			super.write(bytes, offset, length);
			if (payloadWritten.getCount() > 0) {
				payloadWritten.countDown();
				try {
					if (!releasePayloadWrite.await(5, TimeUnit.SECONDS)) {
						throw new AssertionError("Timed out waiting to fail the final response flush");
					}
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new AssertionError(e);
				}
			}
		}

		@Override
		public void flush() throws IOException {
			if (failFlush) {
				throw new IOException("final response flush failed");
			}
			super.flush();
		}
	}
